def f(a):
    if a <= 0:
        return float('inf')
    lhs = 48 * (a**3) * ((2*a + 1)**2)
    rhs = 4 * (a**2) + 1
    return lhs - rhs

# Bisection method to find the root between 0.2 and 0.3
a_low = 0.2
a_high = 0.3
for i in range(10):
    a_mid = (a_low + a_high) / 2
    f_mid = f(a_mid)
    if abs(f_mid) < 1e-6:
        break
    if f_mid < 0:
        a_low = a_mid
    else:
        a_high = a_mid

print(f"Approximate root a: {a_mid}")
print(f"f(a_mid): {f(a_mid)}")

